// Normalise le payload envoyé par lib/notify.ts / triggerN8N
const root = $input.first().json;
const body = root.body ?? root;              // selon 'Received data'
const d = body.data ?? {};
const inner = d.data ?? {};

return [{
  json: {
    eventType: body.eventType ?? 'report_ready',
    notificationId: d.notificationId ?? null,
    kind: d.kind ?? (String(body.eventType).startsWith('alert') ? 'alert' : 'report'),
    title: d.title ?? '(sans titre)',
    summary: d.summary ?? '',
    channels: d.channels ?? [],
    recipients: Array.isArray(d.recipients) ? d.recipients : [],
    recipientsStr: (d.recipients ?? []).join(','),
    alertLevel: d.alertLevel ?? null,
    reportId: d.reportId ?? null,
    pdfFilename: d.pdfFilename ?? 'rapport.pdf',
    pdfBase64: d.pdfBase64 ?? null,
    metrics: inner,
    wantsEmail: (d.channels ?? []).includes('email'),
    wantsSlack: (d.channels ?? []).includes('slack'),
  },
  binary: d.pdfBase64
    ? { pdf: { data: d.pdfBase64, mimeType: 'application/pdf', fileName: d.pdfFilename ?? 'rapport.pdf' } }
    : {},
}];
